  448: /****************************************************************************
  449:  * Name: esp_mipi_dsi_set_cmd_speed
  450:  *
  451:  * Description:
  452:  *   Configure generic/DCS packet speed (LP vs HS) for command-mode
  453:  *   transfers.
  454:  *
  455:  * Input Parameters:
  456:  *   hal     - MIPI-DSI HAL context
  457:  *   use_lpm - true for low-power mode; false for high-speed
  458:  *
  459:  * Returned Value:
  460:  *   None
  461:  *
  462:  ****************************************************************************/
  463: 
  464: static void esp_mipi_dsi_set_cmd_speed(FAR mipi_dsi_hal_context_t *hal,
  465:                                        bool use_lpm)
  466: {
  467:   mipi_dsi_ll_trans_speed_mode_t speed =
  468:     use_lpm ? MIPI_DSI_LL_TRANS_SPEED_LP : MIPI_DSI_LL_TRANS_SPEED_HS;
  469: 
  470:   mipi_dsi_host_ll_set_gen_short_wr_speed_mode(hal->host, 0, speed);
  471:   mipi_dsi_host_ll_set_gen_short_wr_speed_mode(hal->host, 1, speed);
  472:   mipi_dsi_host_ll_set_gen_short_wr_speed_mode(hal->host, 2, speed);
  473:   mipi_dsi_host_ll_set_gen_long_wr_speed_mode(hal->host, speed);
  474:   mipi_dsi_host_ll_set_gen_short_rd_speed_mode(hal->host, 0, speed);
  475:   mipi_dsi_host_ll_set_gen_short_rd_speed_mode(hal->host, 1, speed);
  476:   mipi_dsi_host_ll_set_gen_short_rd_speed_mode(hal->host, 2, speed);
  477:   mipi_dsi_host_ll_set_dcs_short_wr_speed_mode(hal->host, 0, speed);
  478:   mipi_dsi_host_ll_set_dcs_short_wr_speed_mode(hal->host, 1, speed);
  479:   mipi_dsi_host_ll_set_dcs_long_wr_speed_mode(hal->host, speed);
  480:   mipi_dsi_host_ll_set_dcs_short_rd_speed_mode(hal->host, 0, speed);
  481:   mipi_dsi_host_ll_set_mrps_speed_mode(hal->host, speed);
  482: }
