  484: /****************************************************************************
  485:  * Name: esp_mipi_dsi_attach
  486:  *
  487:  * Description:
  488:  *   Attach a MIPI-DSI device (panel) to this host. Updates the PHY data
  489:  *   lane count if the device requests a different lane configuration.
  490:  *
  491:  * Input Parameters:
  492:  *   host   - MIPI-DSI host instance
  493:  *   device - Device to attach (must not be NULL)
  494:  *
  495:  * Returned Value:
  496:  *   Zero (OK) on success; a negated errno value on failure
  497:  *   (-EINVAL, -EBUSY, or lock failure).
  498:  *
  499:  ****************************************************************************/
  500: 
  501: static int esp_mipi_dsi_attach(FAR struct mipi_dsi_host *host,
  502:                                FAR struct mipi_dsi_device *device)
  503: {
  504:   FAR struct esp_mipi_dsi_priv_s *priv =
  505:     (FAR struct esp_mipi_dsi_priv_s *)host;
  506:   int ret;
  507: 
  508:   if (device == NULL)
  509:     {
  510:       return -EINVAL;
  511:     }
  512: 
  513:   ret = nxmutex_lock(&priv->lock);
  514:   if (ret < 0)
  515:     {
  516:       return ret;
  517:     }
  518: 
  519:   if (priv->device != NULL)
  520:     {
  521:       nxmutex_unlock(&priv->lock);
  522:       return -EBUSY;
  523:     }
  524: 
  525:   if (device->lanes == 0 || device->lanes > MIPI_DSI_LL_MAX_DATA_LANES)
  526:     {
  527:       nxmutex_unlock(&priv->lock);
  528:       return -EINVAL;
  529:     }
  530: 
  531:   priv->device = device;
  532:   device->host = host;
  533: 
  534:   /* Prefer device lane count when attached (panel will set this in Phase 3).
  535:    * PHY lane number was already programmed at host init from Kconfig.
  536:    */
  537: 
  538:   if (device->lanes != priv->num_data_lanes)
  539:     {
  540:       mipi_dsi_phy_ll_set_data_lane_number(priv->hal.host, device->lanes);
  541:       priv->num_data_lanes = device->lanes;
  542:     }
  543: 
  544:   nxmutex_unlock(&priv->lock);
  545: 
  546:   vinfo("esp_mipi_dsi: attached device '%s' lanes=%u fmt=%u flags=0x%lx\n",
  547:         device->name, device->lanes, device->format,
  548:         (unsigned long)device->mode_flags);
  549:   return OK;
  550: }
