  552: /****************************************************************************
  553:  * Name: esp_mipi_dsi_detach
  554:  *
  555:  * Description:
  556:  *   Detach a previously attached MIPI-DSI device from this host.
  557:  *
  558:  * Input Parameters:
  559:  *   host   - MIPI-DSI host instance
  560:  *   device - Device to detach (must match the currently attached device)
  561:  *
  562:  * Returned Value:
  563:  *   Zero (OK) on success; a negated errno value on failure.
  564:  *
  565:  ****************************************************************************/
  566: 
  567: static int esp_mipi_dsi_detach(FAR struct mipi_dsi_host *host,
  568:                                FAR struct mipi_dsi_device *device)
  569: {
  570:   FAR struct esp_mipi_dsi_priv_s *priv =
  571:     (FAR struct esp_mipi_dsi_priv_s *)host;
  572:   int ret;
  573: 
  574:   ret = nxmutex_lock(&priv->lock);
  575:   if (ret < 0)
  576:     {
  577:       return ret;
  578:     }
  579: 
  580:   if (priv->device == NULL || priv->device != device)
  581:     {
  582:       nxmutex_unlock(&priv->lock);
  583:       return -EINVAL;
  584:     }
  585: 
  586:   priv->device = NULL;
  587:   device->host = NULL;
  588:   nxmutex_unlock(&priv->lock);
  589:   return OK;
  590: }
