  592: /****************************************************************************
  593:  * Name: esp_mipi_dsi_wait_cmd_not_full
  594:  *
  595:  * Description:
  596:  *   Poll until the generic command FIFO has space for a new header, or
  597:  *   until MIPI_DSI_FIFO_TIMEOUT_MS elapses.
  598:  *
  599:  * Input Parameters:
  600:  *   hal  - MIPI-DSI HAL context
  601:  *   what - Context string used in the timeout error log
  602:  *
  603:  * Returned Value:
  604:  *   Zero (OK) on success; -ETIMEDOUT if the FIFO stays full.
  605:  *
  606:  ****************************************************************************/
  607: 
  608: static int esp_mipi_dsi_wait_cmd_not_full(FAR mipi_dsi_hal_context_t *hal,
  609:                                           FAR const char *what)
  610: {
  611:   int i;
  612: 
  613:   for (i = 0; i < MIPI_DSI_FIFO_TIMEOUT_MS; i++)
  614:     {
  615:       if (!mipi_dsi_host_ll_gen_is_cmd_fifo_full(hal->host))
  616:         {
  617:           return OK;
  618:         }
  619: 
  620:       up_mdelay(1);
  621:     }
  622: 
  623:   verr("esp_mipi_dsi: %s timeout (%d ms)\n", what, MIPI_DSI_FIFO_TIMEOUT_MS);
  624:   return -ETIMEDOUT;
  625: }
  626: 
  627: /****************************************************************************
  628:  * Name: esp_mipi_dsi_wait_pld_not_full
  629:  *
  630:  * Description:
  631:  *   Poll until the generic write payload FIFO has space, or until
  632:  *   MIPI_DSI_FIFO_TIMEOUT_MS elapses.
  633:  *
  634:  * Input Parameters:
  635:  *   hal  - MIPI-DSI HAL context
  636:  *   what - Context string used in the timeout error log
  637:  *
  638:  * Returned Value:
  639:  *   Zero (OK) on success; -ETIMEDOUT if the FIFO stays full.
  640:  *
  641:  ****************************************************************************/
  642: 
  643: static int esp_mipi_dsi_wait_pld_not_full(FAR mipi_dsi_hal_context_t *hal,
  644:                                           FAR const char *what)
  645: {
  646:   int i;
  647: 
  648:   for (i = 0; i < MIPI_DSI_FIFO_TIMEOUT_MS; i++)
  649:     {
  650:       if (!mipi_dsi_host_ll_gen_is_write_fifo_full(hal->host))
  651:         {
  652:           return OK;
  653:         }
  654: 
  655:       up_mdelay(1);
  656:     }
  657: 
  658:   verr("esp_mipi_dsi: %s timeout (%d ms)\n", what,
  659:        MIPI_DSI_FIFO_TIMEOUT_MS);
  660:   return -ETIMEDOUT;
  661: }
  662: 
  663: /****************************************************************************
  664:  * Name: esp_mipi_dsi_wait_cmd_empty
  665:  *
  666:  * Description:
  667:  *   Wait until the generic command FIFO drains.  An unanswered ACK/BTA
  668:  *   leaves the entry pending and would otherwise block forever.
  669:  *
  670:  * Input Parameters:
  671:  *   hal  - MIPI-DSI HAL context
  672:  *   what - Context string used in the timeout error log
  673:  *
  674:  * Returned Value:
  675:  *   Zero (OK) on success; -ETIMEDOUT if the FIFO does not drain.
  676:  *
  677:  ****************************************************************************/
  678: 
  679: static int esp_mipi_dsi_wait_cmd_empty(FAR mipi_dsi_hal_context_t *hal,
  680:                                        FAR const char *what)
  681: {
  682:   int i;
  683: 
  684:   for (i = 0; i < MIPI_DSI_FIFO_TIMEOUT_MS; i++)
  685:     {
  686:       if (mipi_dsi_host_ll_gen_is_cmd_fifo_empty(hal->host))
  687:         {
  688:           return OK;
  689:         }
  690: 
  691:       up_mdelay(1);
  692:     }
  693: 
  694:   verr("esp_mipi_dsi: %s timeout (%d ms)\n", what,
  695:        MIPI_DSI_FIFO_TIMEOUT_MS);
  696:   return -ETIMEDOUT;
  697: }
