  699: /****************************************************************************
  700:  * Name: esp_mipi_dsi_write_short
  701:  *
  702:  * Description:
  703:  *   Transmit a short DCS/generic packet by writing the packet header to
  704:  *   the generic command FIFO and waiting for it to drain.
  705:  *
  706:  * Input Parameters:
  707:  *   hal    - MIPI-DSI HAL context
  708:  *   vc     - Virtual channel (0..3)
  709:  *   dt     - MIPI-DSI data type
  710:  *   header - Two-byte short-packet payload / parameters
  711:  *
  712:  * Returned Value:
  713:  *   Zero (OK) on success; a negated errno value on failure.
  714:  *
  715:  ****************************************************************************/
  716: 
  717: static int esp_mipi_dsi_write_short(FAR mipi_dsi_hal_context_t *hal,
  718:                                     uint8_t vc, mipi_dsi_data_type_t dt,
  719:                                     uint16_t header)
  720: {
  721:   uint8_t msb = (header >> 8) & 0xff;
  722:   uint8_t lsb = header & 0xff;
  723:   int ret;
  724: 
  725:   ret = esp_mipi_dsi_wait_cmd_not_full(hal, "cmd FIFO full (short)");
  726:   if (ret < 0)
  727:     {
  728:       return ret;
  729:     }
  730: 
  731:   mipi_dsi_host_ll_gen_set_packet_header(hal->host, vc, dt, msb, lsb);
  732:   return esp_mipi_dsi_wait_cmd_empty(hal, "cmd FIFO drain (short)");
  733: }
  734: 
  735: /****************************************************************************
  736:  * Name: esp_mipi_dsi_write_long
  737:  *
  738:  * Description:
  739:  *   Transmit a long DCS/generic packet: push the payload into the write
  740:  *   FIFO in 32-bit words, then write the packet header with the length.
  741:  *
  742:  * Input Parameters:
  743:  *   hal - MIPI-DSI HAL context
  744:  *   vc  - Virtual channel (0..3)
  745:  *   dt  - MIPI-DSI data type
  746:  *   buf - Payload bytes (may be NULL only when len is 0)
  747:  *   len - Payload length in bytes
  748:  *
  749:  * Returned Value:
  750:  *   Zero (OK) on success; a negated errno value on failure.
  751:  *
  752:  ****************************************************************************/
  753: 
  754: static int esp_mipi_dsi_write_long(FAR mipi_dsi_hal_context_t *hal,
  755:                                    uint8_t vc, mipi_dsi_data_type_t dt,
  756:                                    FAR const uint8_t *buf, uint16_t len)
  757: {
  758:   FAR const uint8_t *payload = buf;
  759:   uint32_t remain = len;
  760:   uint32_t temp;
  761:   int ret;
  762: 
  763:   while (remain >= 4)
  764:     {
  765:       memcpy(&temp, payload, sizeof(temp));
  766:       ret = esp_mipi_dsi_wait_pld_not_full(hal,
  767:                                            "payload FIFO full (long)");
  768:       if (ret < 0)
  769:         {
  770:           return ret;
  771:         }
  772: 
  773:       mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
  774:       payload += 4;
  775:       remain -= 4;
  776:     }
  777: 
  778:   if (remain > 0)
  779:     {
  780:       temp = 0;
  781:       memcpy(&temp, payload, remain);
  782:       ret = esp_mipi_dsi_wait_pld_not_full(hal,
  783:                                            "payload FIFO full (long tail)");
  784:       if (ret < 0)
  785:         {
  786:           return ret;
  787:         }
  788: 
  789:       mipi_dsi_host_ll_gen_write_payload_fifo(hal->host, temp);
  790:     }
  791: 
  792:   ret = esp_mipi_dsi_wait_cmd_not_full(hal, "cmd FIFO full (long)");
  793:   if (ret < 0)
  794:     {
  795:       return ret;
  796:     }
  797: 
  798:   mipi_dsi_host_ll_gen_set_packet_header(hal->host, vc, dt,
  799:                                          (len >> 8) & 0xff, len & 0xff);
  800:   return esp_mipi_dsi_wait_cmd_empty(hal, "cmd FIFO drain (long)");
  801: }
  802: 
  803: /****************************************************************************
  804:  * Name: esp_mipi_dsi_read_short
  805:  *
  806:  * Description:
  807:  *   Perform a short-packet read: set the maximum return packet size,
  808:  *   enable BTA, issue the read request, and copy response bytes from the
  809:  *   read FIFO into rx.
  810:  *
  811:  * Input Parameters:
  812:  *   hal    - MIPI-DSI HAL context
  813:  *   vc     - Virtual channel (0..3)
  814:  *   dt     - MIPI-DSI read data type
  815:  *   header - Two-byte short-packet parameters for the read request
  816:  *   rx     - Buffer to receive response bytes
  817:  *   rx_len - Size of rx in bytes
  818:  *
  819:  * Returned Value:
  820:  *   Zero (OK) on success; a negated errno value on failure.
  821:  *
  822:  ****************************************************************************/
  823: 
  824: static int esp_mipi_dsi_read_short(FAR mipi_dsi_hal_context_t *hal,
  825:                                    uint8_t vc, mipi_dsi_data_type_t dt,
  826:                                    uint16_t header, FAR void *rx,
  827:                                    uint16_t rx_len)
  828: {
  829:   FAR uint8_t *receive = rx;
  830:   uint32_t temp;
  831:   uint32_t counter = 0;
  832:   int i;
  833:   int ret;
  834: 
  835:   ret = esp_mipi_dsi_write_short(hal, vc, MIPI_DSI_DT_SET_MAXIMUM_RETURN_PKT,
  836:                                  rx_len);
  837:   if (ret < 0)
  838:     {
  839:       return ret;
  840:     }
  841: 
  842:   mipi_dsi_host_ll_enable_video_mode(hal->host, false);
  843:   mipi_dsi_host_ll_enable_bta(hal->host, true);
  844:   mipi_dsi_host_ll_gen_set_rx_vcid(hal->host, vc);
  845: 
  846:   ret = esp_mipi_dsi_write_short(hal, vc, dt, header);
  847:   if (ret < 0)
  848:     {
  849:       goto errout_bta;
  850:     }
  851: 
  852:   for (i = 0; i < MIPI_DSI_FIFO_TIMEOUT_MS; i++)
  853:     {
  854:       if (!mipi_dsi_host_ll_gen_is_read_cmd_busy(hal->host))
  855:         {
  856:           break;
  857:         }
  858: 
  859:       up_mdelay(1);
  860:     }
  861: 
  862:   if (i >= MIPI_DSI_FIFO_TIMEOUT_MS)
  863:     {
  864:       verr("esp_mipi_dsi: read cmd busy timeout\n");
  865:       ret = -ETIMEDOUT;
  866:       goto errout_bta;
  867:     }
  868: 
  869:   for (i = 0; i < MIPI_DSI_FIFO_TIMEOUT_MS; i++)
  870:     {
  871:       if (!mipi_dsi_host_ll_gen_is_read_fifo_empty(hal->host))
  872:         {
  873:           break;
  874:         }
  875: 
  876:       up_mdelay(1);
  877:     }
  878: 
  879:   if (i >= MIPI_DSI_FIFO_TIMEOUT_MS)
  880:     {
  881:       verr("esp_mipi_dsi: read FIFO empty timeout\n");
  882:       ret = -ETIMEDOUT;
  883:       goto errout_bta;
  884:     }
  885: 
  886:   while (!mipi_dsi_host_ll_gen_is_read_fifo_empty(hal->host))
  887:     {
  888:       temp = mipi_dsi_host_ll_gen_read_payload_fifo(hal->host);
  889:       for (i = 0; i < 4; i++)
  890:         {
  891:           if (counter < rx_len)
  892:             {
  893:               receive[counter++] = (temp >> (8 * i)) & 0xff;
  894:             }
  895:         }
  896:     }
  897: 
  898:   ret = OK;
  899: 
  900: errout_bta:
  901:   mipi_dsi_host_ll_enable_bta(hal->host, false);
  902:   return ret;
"}]}

