  905: /****************************************************************************
  906:  * Name: esp_mipi_dsi_transfer
  907:  *
  908:  * Description:
  909:  *   LP/HS command-mode transfer for DCS and generic short/long packets.
  910:  *   Reads temporarily leave video mode (BTA); writes may run during HS
  911:  *   video blanking when the host is already streaming.
  912:  *
  913:  * Input Parameters:
  914:  *   host - MIPI-DSI host instance
  915:  *   msg  - Transfer descriptor (type, channel, buffers, flags)
  916:  *
  917:  * Returned Value:
  918:  *   Number of bytes transferred on success (tx_len or rx_len); a
  919:  *   negated errno value on failure.
  920:  *
  921:  ****************************************************************************/
  922: 
  923: static ssize_t esp_mipi_dsi_transfer(FAR struct mipi_dsi_host *host,
  924:                                      FAR const struct mipi_dsi_msg *msg)
  925: {
  926:   FAR struct esp_mipi_dsi_priv_s *priv =
  927:     (FAR struct esp_mipi_dsi_priv_s *)host;
  928:   FAR mipi_dsi_hal_context_t *hal = &priv->hal;
  929:   FAR const uint8_t *tx = msg->tx_buf;
  930:   bool was_video;
  931:   bool is_read;
  932:   bool use_lpm;
  933:   uint16_t header;
  934:   int ret;
  935: 
  936:   if (msg == NULL)
  937:     {
  938:       return -EINVAL;
  939:     }
  940: 
  941:   ret = nxmutex_lock(&priv->lock);
  942:   if (ret < 0)
  943:     {
  944:       return ret;
  945:     }
  946: 
  947:   if (!priv->initialized)
  948:     {
  949:       nxmutex_unlock(&priv->lock);
  950:       return -EAGAIN;
  951:     }
  952: 
  953:   /* Keep HS video running for LP command writes (lp_cmd_en in
  954:    * blanking). Only tear down video for reads (need BTA / cmd mode).
  955:    */
  956: 
  957:   was_video = priv->video_running;
  958:   is_read = (msg->rx_len > 0 && msg->rx_buf != NULL);
  959: 
  960:   if (was_video && is_read)
  961:     {
  962:       mipi_dsi_brg_ll_enable_dpi_output(hal->bridge, false);
  963:       mipi_dsi_host_ll_enable_video_mode(hal->host, false);
  964:     }
  965:   else if (!was_video)
  966:     {
  967:       mipi_dsi_host_ll_enable_video_mode(hal->host, false);
  968:     }
  969: 
  970:   use_lpm = (msg->flags & MIPI_DSI_MSG_USE_LPM) != 0;
  971:   esp_mipi_dsi_set_cmd_speed(hal, use_lpm);
  972: 
  973:   /* Only request ACK when the message asks for it.
  974:    * An unanswered BTA blocks the generic cmd FIFO.
  975:    */
  976: 
  977:   mipi_dsi_host_ll_enable_cmd_ack(hal->host,
  978:                                 (msg->flags & MIPI_DSI_MSG_REQ_ACK) != 0);
  979: 
  980:   if (mipi_dsi_packet_format_is_short(msg->type))
  981:     {
  982:       header = 0;
  983:       if (msg->tx_len >= 1 && tx != NULL)
  984:         {
  985:           header |= tx[0];
  986:         }
  987: 
  988:       if (msg->tx_len >= 2 && tx != NULL)
  989:         {
  990:           header |= ((uint16_t)tx[1]) << 8;
  991:         }
  992: 
  993:       if (is_read)
  994:         {
  995:           ret = esp_mipi_dsi_read_short(hal, msg->channel,
  996:                                         (mipi_dsi_data_type_t)msg->type,
