 1042: /****************************************************************************
 1043:  * Name: esp_mipi_dsi_wait_phy_ready
 1044:  *
 1045:  * Description:
 1046:  *   Wait for the MIPI PHY PLL to lock and for all configured data lanes
 1047:  *   to enter stop state after bring-up.
 1048:  *
 1049:  * Input Parameters:
 1050:  *   priv - Driver private state
 1051:  *
 1052:  * Returned Value:
 1053:  *   Zero (OK) on success; -ETIMEDOUT if PLL lock or lane stop-state fails.
 1054:  *
 1055:  ****************************************************************************/
 1056: 
 1057: static int esp_mipi_dsi_wait_phy_ready(FAR struct esp_mipi_dsi_priv_s *priv)
 1058: {
 1059:   int i;
 1060: 
 1061:   for (i = 0; i < MIPI_DSI_PHY_LOCK_RETRIES; i++)
 1062:     {
 1063:       if (mipi_dsi_phy_ll_is_pll_locked(priv->hal.host))
 1064:         {
 1065:           break;
 1066:         }
 1067: 
 1068:       up_mdelay(1);
 1069:     }
 1070: 
 1071:   if (i >= MIPI_DSI_PHY_LOCK_RETRIES)
 1072:     {
 1073:       verr("esp_mipi_dsi: PHY PLL lock timeout\n");
 1074:       return -ETIMEDOUT;
 1075:     }
 1076: 
 1077:   for (i = 0; i < MIPI_DSI_PHY_LOCK_RETRIES; i++)
 1078:     {
 1079:       if (mipi_dsi_phy_ll_are_lanes_stopped(priv->hal.host,
 1080:                                             priv->num_data_lanes))
 1081:         {
 1082:           return OK;
 1083:         }
 1084: 
 1085:       up_mdelay(1);
 1086:     }
 1087: 
 1088:   verr("esp_mipi_dsi: PHY lanes stop-state timeout\n");
 1089:   return -ETIMEDOUT;
 1090: }
