 1108: static int esp_mipi_dsi_hw_init(FAR struct esp_mipi_dsi_priv_s *priv)
 1109: {
 1110:   mipi_dsi_hal_config_t hal_config;
 1111:   mipi_dsi_phy_pllref_clock_source_t phy_clk_src;
 1112:   uint32_t phy_clk_src_freq_hz = 0;
 1113:   esp_err_t err;
 1114:   int bus_id = priv->host.bus;
 1115:   int ret;
 1116: 
 1117:   if (priv->num_data_lanes == 0 ||
 1118:       priv->num_data_lanes > MIPI_DSI_LL_MAX_DATA_LANES)
 1119:     {
 1120:       return -EINVAL;
 1121:     }
 1122: 
 1123:   if (priv->lane_bit_rate_mbps < MIPI_DSI_LL_MIN_PHY_MBPS ||
 1124:       priv->lane_bit_rate_mbps > MIPI_DSI_LL_MAX_PHY_MBPS)
 1125:     {
 1126:       return -EINVAL;
 1127:     }
 1128: 
 1129:   PERIPH_RCC_ATOMIC()
 1130:     {
 1131:       mipi_dsi_ll_enable_bus_clock(bus_id, true);
 1132:       mipi_dsi_ll_reset_register(bus_id);
 1133:     }
 1134: 
 1135: #ifdef CONFIG_ESP32P4_SELECTS_REV_LESS_V3
 1136:   phy_clk_src = MIPI_DSI_PHY_PLLREF_CLK_SRC_DEFAULT_LEGACY;
 1137: #else
