 1139: #endif
 1140: 
 1141:   err = esp_clk_tree_enable_src((soc_module_clk_t)phy_clk_src, true);
 1142:   if (err != ESP_OK)
 1143:     {
 1144:       verr("esp_mipi_dsi: enable PHY PLL ref clk failed: %d\n",
 1145:            (int)err);
 1146:       return -EIO;
 1147:     }
 1148: 
 1149:   priv->phy_pllref_clk_src = (soc_module_clk_t)phy_clk_src;
 1150: 
 1151:   err = esp_clk_tree_enable_src(
 1152:           (soc_module_clk_t)MIPI_DSI_PHY_CFG_CLK_SRC_DEFAULT, true);
 1153:   if (err != ESP_OK)
 1154:     {
 1155:       verr("esp_mipi_dsi: enable PHY cfg clk failed: %d\n",
 1156:            (int)err);
 1157:       return -EIO;
 1158:     }
 1159: 
 1160:   priv->phy_cfg_clk_src =
 1161:     (soc_module_clk_t)MIPI_DSI_PHY_CFG_CLK_SRC_DEFAULT;
 1162: 
 1163:   PERIPH_RCC_ATOMIC()
 1164:     {
 1165:       mipi_dsi_ll_set_phy_config_clock_source(bus_id,
 1166:                                           MIPI_DSI_PHY_CFG_CLK_SRC_DEFAULT);
 1167:       mipi_dsi_ll_enable_phy_config_clock(bus_id, true);
 1168:       mipi_dsi_ll_set_phy_pllref_clock_source(bus_id, phy_clk_src);
 1169:       mipi_dsi_ll_set_phy_pll_ref_clock_div(bus_id, 1);
 1170:       mipi_dsi_ll_enable_phy_pllref_clock(bus_id, true);
 1171:     }
 1172: 
 1173:   memset(&hal_config, 0, sizeof(hal_config));
 1174:   hal_config.bus_id = bus_id;
 1175:   hal_config.lane_bit_rate_mbps = priv->lane_bit_rate_mbps;
 1176:   hal_config.num_data_lanes = priv->num_data_lanes;
 1177:   mipi_dsi_hal_init(&priv->hal, &hal_config);
 1178: 
 1179:   err = esp_clk_tree_src_get_freq_hz(phy_clk_src,
 1180:                                      ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
 1181:                                      &phy_clk_src_freq_hz);
 1182:   if (err != ESP_OK || phy_clk_src_freq_hz == 0)
 1183:     {
 1184:       verr("esp_mipi_dsi: get PHY clk freq failed: %d\n",
 1185:            (int)err);
 1186:       return -EIO;
 1187:     }
 1188: 
 1189:   mipi_dsi_hal_configure_phy_pll(&priv->hal, phy_clk_src_freq_hz,
 1190:                                  priv->lane_bit_rate_mbps);
 1191: 
 1192:   ret = esp_mipi_dsi_wait_phy_ready(priv);
 1193:   if (ret < 0)
 1194:     {
 1195:       return ret;
 1196:     }
 1197: 
 1198:   mipi_dsi_host_ll_enable_video_mode(priv->hal.host, false);
 1199:   mipi_dsi_host_ll_set_clock_lane_state(priv->hal.host,
 1200:                                         MIPI_DSI_LL_CLOCK_LANE_STATE_AUTO);
 1201:   mipi_dsi_phy_ll_set_switch_time(priv->hal.host, 50, 104, 46, 128);
 1202: 
 1203:   mipi_dsi_host_ll_enable_rx_crc(priv->hal.host, true);
 1204:   mipi_dsi_host_ll_enable_rx_ecc(priv->hal.host, true);
 1205:   mipi_dsi_host_ll_enable_tx_eotp(priv->hal.host, true, false);
 1206: 
 1207:   mipi_dsi_host_ll_set_timeout_clock_division(
 1208:     priv->hal.host,
 1209:     (uint32_t)roundf(priv->lane_bit_rate_mbps / 8.0f /
 1210:                      MIPI_DSI_TIMEOUT_CLK_MHZ));
 1211:   mipi_dsi_host_ll_set_escape_clock_division(
 1212:     priv->hal.host,
 1213:     (uint32_t)roundf(priv->lane_bit_rate_mbps / 8.0f /
 1214:                      MIPI_DSI_ESCAPE_CLK_MHZ));
 1215:   mipi_dsi_host_ll_set_timeout_count(priv->hal.host, 0, 0, 0, 0, 0, 0, 0);
 1216:   mipi_dsi_phy_ll_set_max_read_time(priv->hal.host, 6000);
 1217:   mipi_dsi_phy_ll_set_stop_wait_time(priv->hal.host, 0x3f);
 1218: 
 1219:   mipi_dsi_host_ll_enable_te_ack(priv->hal.host, false);
 1220: 
 1221:   /* Keep ACK off unless a transfer sets MIPI_DSI_MSG_REQ_ACK.  An
 1222:    * unanswered BTA holds the generic cmd FIFO and looks like a boot hang.
 1223:    */
 1224: 
 1225:   mipi_dsi_host_ll_enable_cmd_ack(priv->hal.host, false);
 1226:   esp_mipi_dsi_set_cmd_speed(&priv->hal, true);
 1227: 
 1228:   return OK;
