 1255: int esp_mipi_dsi_initialize(
 1256:       FAR const struct esp_mipi_dsi_bus_config_s *cfg)
 1257: {
 1258:   FAR struct esp_mipi_dsi_priv_s *priv = &g_esp_mipi_dsi;
 1259:   int ret;
 1260: 
 1261:   ret = nxmutex_lock(&priv->lock);
 1262:   if (ret < 0)
 1263:     {
 1264:       return ret;
 1265:     }
 1266: 
 1267:   if (priv->initialized)
 1268:     {
 1269:       nxmutex_unlock(&priv->lock);
 1270:       return OK;
 1271:     }
 1272: 
 1273:   /* Board may override Kconfig; zero / NULL means use defaults. */
 1274: 
 1275:   if (cfg != NULL && cfg->num_data_lanes != 0)
 1276:     {
 1277:       priv->num_data_lanes = cfg->num_data_lanes;
 1278:     }
 1279:   else
 1280:     {
 1281:       priv->num_data_lanes = CONFIG_ESPRESSIF_MIPI_DSI_LANES;
 1282:     }
 1283: 
 1284:   if (cfg != NULL && cfg->lane_bit_rate_mbps != 0)
 1285:     {
 1286:       priv->lane_bit_rate_mbps = (float)cfg->lane_bit_rate_mbps;
 1287:     }
 1288:   else
 1289:     {
 1290:       priv->lane_bit_rate_mbps =
 1291:         (float)CONFIG_ESPRESSIF_MIPI_DSI_LANE_BITRATE_MBPS;
 1292:     }
 1293: 
 1294:   ret = esp_mipi_dsi_hw_init(priv);
 1295:   if (ret < 0)
 1296:     {
 1297:       nxmutex_unlock(&priv->lock);
 1298:       return ret;
 1299:     }
 1300: 
 1301:   ret = mipi_dsi_host_register(&priv->host);
 1302:   if (ret < 0)
 1303:     {
 1304:       nxmutex_unlock(&priv->lock);
 1305:       verr("esp_mipi_dsi: host register failed: %d\n", ret);
 1306:       return ret;
 1307:     }
 1308: 
 1309:   /* Only mark ready after registration succeeds so host_get() / retries
 1310:    * do not observe a half-initialized host.
 1311:    */
