 1313:   priv->initialized = true;
 1314:   nxmutex_unlock(&priv->lock);
 1315: 
 1316:   vinfo("esp_mipi_dsi: host registered (bus=%d, lanes=%u, "
 1317:          "%u Mbps/lane)\n",
 1318:          priv->host.bus, priv->num_data_lanes,
 1319:          (unsigned int)(priv->lane_bit_rate_mbps + 0.5f));
