  457: 
  458: /****************************************************************************
  459:  * Framebuffer character device glue (/dev/fb0) for LVGL & apps.
  460:  * The pixel surface is the PSRAM buffer already bound to DW-GDMA.
  461:  ****************************************************************************/
  462: 
  463: static int disp_getvideoinfo(FAR struct fb_vtable_s *vtable,
  464:                              FAR struct fb_videoinfo_s *vinfo)
  465: {
  466:   vinfo->fmt     = FB_FMT_RGB16_565;
  467:   vinfo->xres    = FB_W;
  468:   vinfo->yres    = FB_H;
  469:   vinfo->nplanes = 1;
  470:   return OK;
  471: }
  472: 
  473: static int disp_getplaneinfo(FAR struct fb_vtable_s *vtable, int planeno,
  474:                              FAR struct fb_planeinfo_s *pinfo)
  475: {
  476:   if (planeno != 0)
  477:     {
  478:       return -EINVAL;
  479:     }
  480: 
  481:   pinfo->fbmem   = (FAR void *)g_fb;
  482:   pinfo->fblen   = FB_SIZE;
  483:   pinfo->stride   = FB_W * FB_BYTES_PER_PIXEL;
  484:   pinfo->display  = 0;
  485:   pinfo->bpp      = FB_BPP;
  486:   return OK;
  487: }
  488: 
  489: #ifdef CONFIG_FB_UPDATE
  490: static int disp_updatearea(FAR struct fb_vtable_s *vtable,
  491:                            FAR const struct fb_area_s *area)
  492: {
  493:   FAR uint8_t *start;
  494:   size_t len;
  495: 
  496:   if (g_fb == NULL || area == NULL || area->h == 0 ||
  497:       area->y >= FB_H || area->h > FB_H - area->y)
  498:     {
  499:       return -EINVAL;
  500:     }
  501: 
  502:   /* The DMA always scans a complete frame, but only rows touched by LVGL
  503:    * need CPU-to-memory cache writeback.  Flush complete scanlines so the
  504:    * range remains simple and cache-line safe even for a narrow dirty area.
  505:    * This follows ESP-IDF's DPI framebuffer update strategy and avoids a
  506:    * 1.2 MiB writeback for every small clock or touch-label update. */
  507: 
  508:   start = g_fb + (size_t)area->y * FB_W * FB_BYTES_PER_PIXEL;
  509:   len = (size_t)area->h * FB_W * FB_BYTES_PER_PIXEL;
  510: 
  511:   g_update_count++;
  512:   if (g_update_count <= 4)
  513:     {
  514:       printf("DISP: update #%lu x=%u y=%u w=%u h=%u flush=%p+%u\n",
  515:              (unsigned long)g_update_count, area->x, area->y,
  516:              area->w, area->h, start, (unsigned int)len);
  517:     }
  518: 
  519:   return esp_mipi_dsi_flush_framebuffer(start, len);
  520: }
  521: #endif
  522: 
  523: static struct fb_vtable_s g_disp_vtable =
  524: {
  525:   .getvideoinfo = disp_getvideoinfo,
  526:   .getplaneinfo = disp_getplaneinfo,
  527: #ifdef CONFIG_FB_UPDATE
  528:   .updatearea   = disp_updatearea,
  529: #endif
  530: };
  531: 
  532: /* Arch hooks used by fb_register() when CONFIG_VIDEO_FB is enabled */
  533: 
  534: int up_fbinitialize(int display)
  535: {
  536:   return esp32p4_display_init();
  537: }
  538: 
  539: FAR struct fb_vtable_s *up_fbgetvplane(int display, int plane)
  540: {
  541:   return g_ready ? &g_disp_vtable : NULL;
  542: }
